# ============================================================================\n# Client (§18 — тур-оператор работает с клиентами)\n# ============================================================================\n\n@dataclass\nclass Client(Entity):\n    """Клиент — заказчик поездки (§18, §32).\"\"\"\n    entity_type: EntityType = EntityType.CLIENT\n\n    name: str = ""\n    email: str = ""\n    phone: str = ""\n\n    preferences: dict[str, Any] = field(default_factory=dict)\n    budget: float = 0.0\n    currency: str = "RUB"\n\n    travel_history: list[dict[str, Any]] = field(default_factory=list)\n    notes: str = ""\n\n    def to_dict(self, **kwargs: Any) -> dict:\n        d = super().to_dict(**kwargs)\n        d["preferences"] = self.preferences\n        d["travel_history"] = self.travel_history\n        return d\n\n\ndef create_client(\n    name: str = "",\n    email: str = "",\n    phone: str = "",\n    preferences: dict[str, Any] | None = None,\n    budget: float = 0.0,\n    currency: str = "RUB",\n    notes: str = "",\n) -> Client:\n    return Client(\n        name=name or "",\n        email=email or "",\n        phone=phone or "",\n        preferences=preferences or {},\n        budget=budget,\n        currency=currency,\n        notes=notes,\n    )\n